// @ai:generated by=claude-opus-4-6 date=2026-02-27
package manifest

import (
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/maoxiaoyue/hypgo/pkg/schema"
)

// EnrichConfig 控制 Manifest 自動推斷行為
type EnrichConfig struct {
	// InferSummary 從 handler 名、路徑、命令推斷 Summary（預設 true）
	InferSummary bool

	// InferTags 從路徑推斷 Tags（預設 true）
	InferTags bool

	// IncludeFields 在 manifest 中包含 Input/Output 的欄位資訊（預設 true）
	IncludeFields bool

	// LLMEnricher 可選的 LLM 增強器（nil 表示不使用）
	LLMEnricher LLMEnricher
}

// DefaultEnrichConfig 回傳預設配置（純推斷，零成本）。
// IncludeFields 預設開啟：先前預設關閉且無任何呼叫端打開，manifest 從不含 Input/Output
// 的欄位形狀，AI 讀 .hyp/context.yaml 只看得到型別名稱
func DefaultEnrichConfig() EnrichConfig {
	return EnrichConfig{
		InferSummary:  true,
		InferTags:     true,
		IncludeFields: true,
	}
}

// LLMEnricher 定義 LLM 增強的介面
// 實作者可以呼叫 OpenAI、Claude、Gemini 等 API
type LLMEnricher interface {
	// EnrichRoutes 為一批路由生成更精確的描述，直接回填 routes 的空白欄位（Summary / Description）。
	// 收到的都是至少缺其中一項的路由（已含 Tags 等推斷結果）；
	// 一次收到整批，方便把多條路由合併成一個請求
	EnrichRoutes(routes []RouteManifest)
}

// enrichRoute 為單條路由補上 Tags 與 Input / Output 欄位資訊。
// Summary / Description 要等全部路由收集完才由 enrichSummaries 處理（LLM 需整批送出）
func enrichRoute(rm *RouteManifest, schemaRoute *schema.Route, cfg EnrichConfig) {
	// 推斷 Tags（LLM 不產生 tags，先填好可一併作為 prompt 的上下文）
	if cfg.InferTags && len(rm.Tags) == 0 {
		rm.Tags = inferTags(rm)
	}

	// 填入欄位資訊
	if cfg.IncludeFields && schemaRoute != nil {
		if schemaRoute.Input != nil {
			rm.InputFields = schema.FieldsOf(schemaRoute.Input)
		}
		if schemaRoute.Output != nil {
			rm.OutputFields = schema.FieldsOf(schemaRoute.Output)
		}
	}
}

// enrichSummaries 在全部路由收集完後填補 Summary / Description。
// 缺任一項的路由整批交給 LLM；兩項都已宣告的不送：LLM 只回填空白欄位，送了也是白付請求，
// 而且結果是空的、不會進快取，先前每次同步都重送一次。
// LLM 在 Summary 推斷之前執行：先推斷會把 Summary 填滿，LLM 產生的 summary 就永遠被丟棄。
// Summary 推斷是 LLM 未提供（停用或失敗）時的退路
func enrichSummaries(routes []RouteManifest, cfg EnrichConfig) {
	if cfg.LLMEnricher != nil {
		var idx []int
		for i := range routes {
			if routes[i].Summary == "" || routes[i].Description == "" {
				idx = append(idx, i)
			}
		}
		if len(idx) > 0 {
			pending := make([]RouteManifest, len(idx))
			for j, i := range idx {
				pending[j] = routes[i]
			}
			cfg.LLMEnricher.EnrichRoutes(pending)
			for j, i := range idx {
				routes[i] = pending[j]
			}
		}
	}

	if cfg.InferSummary {
		for i := range routes {
			if routes[i].Summary == "" {
				routes[i].Summary = inferSummary(&routes[i])
			}
		}
	}
}

// inferSummary 從 handler 名、路徑、命令推斷 Summary
func inferSummary(rm *RouteManifest) string {
	proto := rm.Protocol
	if proto == "" {
		proto = "rest"
	}

	switch proto {
	case "rest":
		return inferRESTSummary(rm)
	case "grpc":
		return inferGRPCSummary(rm.Command)
	case "bot":
		if rm.Platform != "" {
			return rm.Platform + " command: " + rm.Command
		}
		return "Bot command: " + rm.Command
	case "mcp":
		return "MCP tool: " + humanize(rm.Command)
	case "websocket":
		return "WebSocket: " + humanize(rm.Command)
	case "cli":
		return "CLI command: " + rm.Command
	case "desktop":
		return "Desktop view: " + rm.Command
	default:
		return ""
	}
}

// inferRESTSummary 從 handler 名和路徑推斷 REST 路由的 Summary
func inferRESTSummary(rm *RouteManifest) string {
	// 優先從 handler 名推斷
	if name := primaryHandler(rm.HandlerNames); name != "" {
		// "controllers.(*UserController).Create" → "Create User"
		if parts := strings.Split(name, "."); len(parts) >= 2 {
			method := capitalize(humanizeMethod(strings.TrimSuffix(parts[len(parts)-1], "Handler")))
			// 嘗試從 controller 名取得資源名
			for _, p := range parts {
				p = strings.Trim(p, "(*)")
				if strings.HasSuffix(p, "Controller") {
					resource := strings.TrimSuffix(p, "Controller")
					return method + " " + resource
				}
			}
			return method
		}
	}

	// 從路徑推斷
	if rm.Path != "" {
		resource := extractResource(rm.Path)
		if resource != "" {
			switch rm.Method {
			case "GET":
				if strings.Contains(rm.Path, ":") {
					return "Get " + resource
				}
				return "List " + resource
			case "POST":
				return "Create " + resource
			case "PUT", "PATCH":
				return "Update " + resource
			case "DELETE":
				return "Delete " + resource
			}
		}
	}

	return ""
}

// primaryHandler 回傳代表路由的 handler 名稱：鏈上最後一個具名函式。
// 第一個常是 Handle(authMW, handler) 帶入的中介層（先前推斷出 "auth M W"）；
// 匿名函式（"pkg.Setup.func1"）沒有語意，跳過後改由路徑推斷（先前推斷出 "func1"）
func primaryHandler(names []string) string {
	for i := len(names) - 1; i >= 0; i-- {
		last := names[i][strings.LastIndex(names[i], ".")+1:]
		if !isAnonymousFunc(last) {
			return names[i]
		}
	}
	return ""
}

// isAnonymousFunc 判斷名稱是否為編譯器替匿名函式產生的 "funcN"
func isAnonymousFunc(s string) bool {
	if !strings.HasPrefix(s, "func") || len(s) == len("func") {
		return false
	}
	for _, r := range s[len("func"):] {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// inferGRPCSummary 從 gRPC 命令推斷 Summary
func inferGRPCSummary(command string) string {
	// "UserService/CreateUser" → "Create User (gRPC)"
	parts := strings.Split(command, "/")
	if len(parts) == 2 {
		method := parts[1]
		return capitalize(humanizeMethod(method)) + " (gRPC)"
	}
	return "gRPC: " + command
}

// inferTags 從路徑推斷 Tags
func inferTags(rm *RouteManifest) []string {
	if rm.Path != "" {
		resource := extractResource(rm.Path)
		if resource != "" {
			return []string{strings.ToLower(resource)}
		}
	}

	// 非 REST：從 command 推斷
	if rm.Command != "" {
		parts := strings.Split(rm.Command, "/")
		if len(parts) >= 2 {
			// "UserService/CreateUser" → ["userservice"]
			return []string{strings.ToLower(parts[0])}
		}
	}

	if rm.Platform != "" {
		return []string{rm.Platform}
	}

	return nil
}

// extractResource 從路徑中提取資源名
// "/api/users/:id" → "users"
// "/api/v1/orders" → "orders"
func extractResource(path string) string {
	segments := strings.Split(strings.Trim(path, "/"), "/")
	for i := len(segments) - 1; i >= 0; i-- {
		seg := segments[i]
		if seg == "" || strings.HasPrefix(seg, ":") || strings.HasPrefix(seg, "*") {
			continue
		}
		// 跳過 "api", "v1", "v2" 等前綴
		lower := strings.ToLower(seg)
		if lower == "api" || (len(lower) >= 2 && lower[0] == 'v' && lower[1] >= '0' && lower[1] <= '9') {
			continue
		}
		return capitalize(seg)
	}
	return ""
}

// humanize 將 snake_case 或 kebab-case 轉為可讀字串
func humanize(s string) string {
	s = strings.ReplaceAll(s, "_", " ")
	s = strings.ReplaceAll(s, "-", " ")
	return capitalize(s)
}

// humanizeMethod 將方法名轉為可讀字串，連續大寫視為一個縮寫
// "CreateUser" → "Create User"
// "GetByID" → "Get By ID"（先前逐字母拆成 "Get By I D"）
// "HTTPServer" → "HTTP Server"
func humanizeMethod(method string) string {
	rs := []rune(method)
	var b strings.Builder
	for i, r := range rs {
		if i > 0 && unicode.IsUpper(r) {
			prev := rs[i-1]
			nextLower := i+1 < len(rs) && unicode.IsLower(rs[i+1])
			if unicode.IsLower(prev) || unicode.IsDigit(prev) || (unicode.IsUpper(prev) && nextLower) {
				b.WriteByte(' ')
			}
		}
		b.WriteRune(r)
	}
	return b.String()
}

// capitalize 將首字轉大寫。以 rune 處理：先前 s[:1] 只取一個 byte，
// 非 ASCII 開頭（"訂單"）會被切成不合法的 UTF-8
func capitalize(s string) string {
	r, size := utf8.DecodeRuneInString(s)
	if size == 0 {
		return ""
	}
	return string(unicode.ToUpper(r)) + s[size:]
}
